UPDATE annual_leave_balance_idempotency_record
SET record_status = 'COMPLETED',
    resulting_ledger_entry_id = #{resultingLedgerEntryId},
    resulting_balance_hours = #{resultingBalanceHours},
    resulting_row_version = #{resultingRowVersion},
    completed_at = #{completedAt}
WHERE principal_id = #{principalId}
  AND idempotency_key = #{idempotencyKey}
  AND claim_token = #{claimToken}
  AND record_status = 'PROCESSING'
